const qEl = document.getElementById("q");
const catEl = document.getElementById("cat");
const pillsEl = document.getElementById("cat-pills");
const gridEl = document.getElementById("grid");
const countEl = document.getElementById("count");

const totalCount = CATALOG.reduce((acc, c) => acc + c.count, 0);
const pillList = [{ category: "", label: `All (${totalCount})` }];

CATALOG.forEach((c) => {
  const opt = document.createElement("option");
  opt.value = c.category;
  opt.textContent = `${c.category} (${c.count})`;
  catEl.appendChild(opt);
  pillList.push({ category: c.category, label: `${c.category} (${c.count})` });
});

function esc(s) {
  return String(s).replace(/[&<>"']/g, (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch]));
}

function renderPills() {
  const active = catEl.value;
  pillsEl.innerHTML = pillList.map((p) => `
    <button class="cat-pill" type="button" data-cat="${esc(p.category)}" aria-pressed="${p.category === active}">${esc(p.label)}</button>
  `).join("");
}

function setCategory(cat) {
  catEl.value = cat;
  renderPills();
  render();
}

function render() {
  const q = qEl.value.trim().toLowerCase();
  const cat = catEl.value;
  const items = [];
  for (const c of CATALOG) {
    if (cat && c.category !== cat) continue;
    for (const t of c.tools) {
      const hay = `${t.title} ${t.desc} ${t.tags.join(" ")} ${c.category}`.toLowerCase();
      if (q && !hay.includes(q)) continue;
      items.push({ ...t, category: c.category });
    }
  }
  countEl.textContent = `${items.length} tool${items.length === 1 ? "" : "s"}`;
  gridEl.innerHTML = items.map((t) => `
    <article class="tool-card">
      <div class="tool-top">
        <div>
          <div class="tool-title">${esc(t.title)}</div>
          <div class="tool-cat">${esc(t.category)}</div>
        </div>
        ${t.url ? `<a class="ext-link" href="${esc(t.url)}" target="_blank" rel="noopener noreferrer">Repo ↗</a>` : ""}
      </div>
      <p class="tool-desc">${esc(t.desc || "Curated security tool.")}</p>
      <div class="tags">${t.tags.map((tag) => `<span class="tag" data-tag="${esc(tag)}">${esc(tag)}</span>`).join("")}</div>
    </article>
  `).join("");
}

gridEl.addEventListener("click", (e) => {
  const tagEl = e.target.closest("[data-tag]");
  if (!tagEl) return;
  qEl.value = tagEl.getAttribute("data-tag");
  render();
});

pillsEl.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-cat]");
  if (!btn) return;
  setCategory(btn.getAttribute("data-cat"));
});

qEl.addEventListener("input", render);
catEl.addEventListener("change", () => { renderPills(); render(); });

const params = new URLSearchParams(location.search);
if (params.get("q")) qEl.value = params.get("q");
if (params.get("cat")) catEl.value = params.get("cat");

renderPills();
render();
